// Finder opskrifter der deler flest ingredienser og tags med en given opskrift
const input = $('Start').first().json;
const recipeId = String(input.recipeId || '').trim();
const statement = [
  "MATCH (r:Recipe {id: $recipeId})-[:HAS_INGREDIENT]->(i:Ingredient)<-[:HAS_INGREDIENT]-(o:Recipe)",
  "WITH r, o, collect(i.name) AS shared",
  "OPTIONAL MATCH (r)-[:HAS_TAG]->(t:Tag)<-[:HAS_TAG]-(o)",
  "WITH r, o, shared, count(t) AS sharedTags",
  "RETURN r.name AS forRecipe, o.id AS recipeId, o.name AS name,",
  "  size(shared) AS sharedIngredients, shared, sharedTags, o.rating AS rating,",
  "  'Neo4j graph (Food.com RecipeId ' + o.id + ')' AS source",
  "ORDER BY sharedIngredients DESC, sharedTags DESC LIMIT 5"
].join(' ');
return [{ json: { statements: [{ statement, parameters: { recipeId } }] } }];

// Laver Neo4j's svar om til en læsbar liste til agenten
const res = $input.first().json;
if (res.errors && res.errors.length) {
  return [{ json: { error: res.errors.map(e => e.message).join('; ') } }];
}
const r = res.results[0];
const rows = r.data.map(d => Object.fromEntries(r.columns.map((c, i) => [c, d.row[i]])));
return [{ json: { count: rows.length, results: rows } }];
